/**
 * Universal PlatformIcon router component
 */
export const PlatformIcon: React.FC<PlatformIconProps> = ({
  platform = "",
  className = "w-4 h-4",
  active = false,
}) => {
  const p = (platform || "").toLowerCase().trim();

  const colorClass = active
    ? "text-white drop-shadow-[0_0_8px_rgba(255,255,255,0.4)]"
    : "text-slate-300 group-hover:text-white transition-colors";

  const mergedClass = `${className} ${colorClass}`;

  // 1. Specific Consoles & Handhelds (evaluated first to avoid generic "nintendo" or "playstation" collisions)
  if (p === "switch" || p.includes("nintendo switch") || p === "console_switch") return <NintendoIcon className={mergedClass} />;
  if (p === "snes" || p.includes("super nintendo") || p.includes("super famicom")) return <SnesIcon className={mergedClass} />;
  if (p === "nes" || p.includes("nintendo entertainment system") || p.includes("famicom")) return <NesIcon className={mergedClass} />;
  if (p === "n64" || p.includes("nintendo 64")) return <N64Icon className={mergedClass} />;
  if (p === "gamecube" || p === "gc" || p.includes("gamecube")) return <GameCubeIcon className={mergedClass} />;
  if (p === "wiiu" || p === "wii u" || p.includes("wii u") || p.includes("wiiu")) return <WiiUIcon className={mergedClass} />;
  if (p === "wii" || p.includes("wii")) return <WiiIcon className={mergedClass} />;
  if (p === "gba" || p.includes("game boy advance") || p.includes("gameboy advance")) return <GbaIcon className={mergedClass} />;
  if (p === "gb" || p === "gbc" || p.includes("game boy") || p.includes("gameboy")) return <GameBoyIcon className={mergedClass} />;
  if (p === "3ds" || p.includes("3ds")) return <ThreeDsIcon className={mergedClass} />;
  if (p === "nds" || p === "ds" || p.includes("nintendo ds") || p.includes("nintendods")) return <DsIcon className={mergedClass} />;

  // PlayStation generation specific
  if (p === "ps2" || p.includes("playstation 2") || p.includes("playstation2")) return <Ps2Icon className={mergedClass} />;
  if (p === "ps3" || p.includes("playstation 3") || p.includes("playstation3")) return <Ps3Icon className={mergedClass} />;
  if (p === "psp" || p.includes("playstation portable")) return <PspIcon className={mergedClass} />;
  if (p === "psvita" || p === "vita" || p.includes("playstation vita") || p.includes("ps vita")) return <PsVitaIcon className={mergedClass} />;
  if (p === "ps1" || p === "psx" || p.includes("playstation 1")) return <PlayStationIcon className={mergedClass} />;

  // Sega
  if (p === "genesis" || p.includes("mega drive") || p.includes("megadrive") || p.includes("sega genesis")) return <GenesisIcon className={mergedClass} />;
  if (p === "saturn" || p.includes("sega saturn")) return <SaturnIcon className={mergedClass} />;
  if (p === "dreamcast" || p.includes("sega dreamcast")) return <DreamcastIcon className={mergedClass} />;

  // Atari & Other Retro
  if (p.includes("atari")) return <AtariIcon className={mergedClass} />;
  if (p === "xbox360" || p.includes("xbox 360")) return <Xbox360Icon className={mergedClass} />;

  // 2. PC Stores & Major Platforms
  if (p === "steam") return <SteamIcon className={mergedClass} />;
  if (p === "epic" || p.includes("epic")) return <EpicIcon className={mergedClass} />;
  if (p === "gog") return <GogIcon className={mergedClass} />;
  if (p === "xbox" || p.includes("gamepass")) return <XboxIcon className={mergedClass} />;
  if (p === "battlenet" || p === "battle.net" || p.includes("blizzard")) return <BattleNetIcon className={mergedClass} />;
  if (p === "ea" || p.includes("origin")) return <EaIcon className={mergedClass} />;
  if (p === "ubisoft" || p.includes("uplay")) return <UbisoftIcon className={mergedClass} />;
  if (p === "riot" || p.includes("valorant") || p.includes("league")) return <RiotIcon className={mergedClass} />;
  if (p === "amazon" || p.includes("prime")) return <AmazonIcon className={mergedClass} />;
  if (p === "psn" || p.includes("playstation")) return <PlayStationIcon className={mergedClass} />;
  if (p.includes("nintendo")) return <NintendoIcon className={mergedClass} />;
  if (p === "retroachievements" || p === "ra") return <RetroAchievementsIcon className={mergedClass} />;
  if (p === "googleplay" || p.includes("google")) return <GooglePlayIcon className={mergedClass} />;
  if (p === "roblox") return <RobloxIcon className={mergedClass} />;

  // Generic Emulation fallback
  if (p === "emulation" || p.includes("emulator") || p.includes("rom") || p.includes("arcade")) {
    return <ArcadeIcon className={mergedClass} />;
  }

  return <LocalPcIcon className={mergedClass} />;
};
